778	    // ── P2.6 (PRODIGY ONLY): STAGED cross-ALL-tensors d-estimate. PORT of the
779	    //    decoder/vit TC kernels' P2.6 (fused_decoder_megakernel.cuh:514-568) onto the
780	    //    mamba constant tables.
781	    //    ⚠ LANDED-DORMANT / NOT PRODUCTION-ROUTED: mamba×prodigy is BLOCKED on a
782	    //    PRE-EXISTING A/A/A determinism failure SHARED by the decoder/vit prodigy P2.6
783	    //    (this port faithfully reproduces them; the failure is NOT in this code). The
784	    //    dispatch.cpp mamba carve-out (optimizer!="prodigy") + the Python has_l3_real
785	    //    gate keep this branch unreachable from the race until the shared prodigy P2.6
786	    //    (opt_stages_precompute.cuh) / GridBarrier (megakernel_common.cuh) is fixed by
787	    //    its owner. Kept here (if-constexpr'd, proven byte-identical for every non-Prodigy
788	    //    Opt) as the ready starting point for that fix. See dispatch.py's ⚠ escalation.
789	    //    The apply tail (apply_optimizer<Prodigy>) reads
790	    //    st.d_factor (the effective LR scale d), a GLOBAL reduction over EVERY element
791	    //    of EVERY parameter tensor. We compute it here, BYTE-FAITHFUL to the live eager
792	    //    multi-tensor path (prodigy_sm90.cuh:465-544, the order prodigy.py →
793	    //    _ops.prodigy_fused_step actually executes):
794	    //      d_prev  = persisted d_lr  (step 1: d0 cold-start — the zero-init state slot
795	    //                would give d_prev=0 ⇒ d=0 ⇒ frozen params; eager inits _d_lr=d0,
796	    //                so seed it here, the grokfast-style step-1 fix)
797	    //      r_ema  <- beta3·r_ema + Σ d_prev²·<g, p0−p>     (decay persisted SCALAR,
798	    //      s_ema  <- beta3·s_ema + Σ d_prev²·|g|            then add this step's Σ)
799	    //      d       = max(d_prev, d_coef·r_ema/|s_ema|)      (prodigy_update_d; d_coef
800	    //                scales ONLY the candidate — persisted r_ema stays UNSCALED)
801	    //    DETERMINISM (COMPONENT_CONTRACT): NO float atomic. Each CTA publishes its
802	    //    (r,s) into per-CTA slots (opt_reduce) → grid barrier → CTA0 owner-sums in
803	    //    ascending index order → writes d back to the persisted slot + a broadcast
804	    //    slot. The decay is on the persisted SCALARS (not the per-CTA partials): the
805	    //    work-steal queue reassigns tensors to CTAs across steps, so a per-CTA EMA is
806	    //    undefined — the live form is a scalar EMA (prodigy_sm90.cuh:488). Guarded so
807	    //    every other opt's P3 is byte-identical (no extra barrier/work).
808	    // DETERMINISM — FIXED-PARTITION reduction (mirrors the A/A/A-CLEAN GrokAdamW
809	    // P2.5 + the decoder/vit twins' P2.6), NOT the work-steal task-queue drain.
810	    // WHY THIS SHAPE (the A/A/A determinism leg): the work-steal phaseA drained the
811	    // global TaskQueue (atomicAdd(g_next_task)) in timing-dependent claim order, so
812	    // each CTA's (r,s) slot could be a different tensor subset run-to-run; with non-
813	    // associative fp32 add the partials regroup differently and the owner's d can
814	    // differ at ULP level from step>=2 — a COMPONENT_CONTRACT deterministic-reduction
815	    // violation (not reproducible BY CONSTRUCTION). A FIXED contiguous element range
816	    // per CTA over the FLAT [0,kMambaTotalElems) arrays (params/param_init/grad are
817	    // parallel flat blobs → flat Σ == cross-tensor Σ) with a plain sync() is the
818	    // IDENTICAL shape as the A/A/A-CLEAN GrokAdamW P2.5 — deterministic by
819	    // construction. Per-element math still CALLS canonical prodigy_partials_step
820	    // (prodigy.h, single-source). g_next_task is UNTOUCHED (B2 reset it), so P3's
821	    // drain is unchanged — no sync_reset in P2.6. (mamba×prodigy is dispatch-gated to
822	    // eager today on a SEPARATE mamba scan/forward determinism issue; this keeps the
823	    // landed-dormant P2.6 correct + deterministic.)
824	    if constexpr (Opt == OptId::Prodigy) {
825	        float* r_part = opt_reduce;                  // [nCTA] per-CTA Σ d²·<g,p0−p>
826	        float* s_part = opt_reduce + nCTA;           // [nCTA] per-CTA Σ d²·|g|
827	        float* d_bc   = opt_reduce + 2 * nCTA;       // [1] reduced-d broadcast
828	        const float d_prev = (step == 1) ? st.d0 : st.prodigy_persist[2];
829	        const int64_t total_p = kMambaTotalElems;
830	        const int64_t pbase = total_p / nCTA, prem = total_p % nCTA;
831	        const int64_t pe0 = (int64_t)cta * pbase + (cta < prem ? cta : prem);
832	        const int64_t pecnt = pbase + (cta < prem ? 1 : 0);
833	        float r_acc = 0.0f, s_acc = 0.0f;
834	        for (int64_t i = threadIdx.x; i < pecnt; i += blockDim.x) {
835	            algo::prodigy_partials_step(params, st.param_init, grad,
836	                                        d_prev, pe0 + i, r_acc, s_acc);
837	        }
838	        float r_block, s_block;
839	        prim::block_reduce_sum2_f32(r_acc, s_acc, r_block, s_block);
840	        if (threadIdx.x == 0) { r_part[cta] = r_block; s_part[cta] = s_block; }
841	        bar.sync();   // B2.6a: all per-CTA (r,s) partials published & visible
842	        if (cta == 0 && threadIdx.x == 0) {
843	            float r_step = 0.0f, s_step = 0.0f;     // ascending-CTA owner-sum
844	            for (int c = 0; c < nCTA; ++c) { r_step += r_part[c]; s_step += s_part[c]; }
845	            const float r_ema = st.beta3 * st.prodigy_persist[0] + r_step;
846	            const float s_ema = st.beta3 * st.prodigy_persist[1] + s_step;
847	            const float d_new = algo::prodigy_update_d(d_prev, st.d_coef * r_ema, s_ema);
848	            st.prodigy_persist[0] = r_ema;          // persist UNSCALED EMA
849	            st.prodigy_persist[1] = s_ema;
850	            st.prodigy_persist[2] = d_new;          // persisted d_lr for next step
851	            d_bc[0]               = d_new;          // broadcast to all CTAs
852	        }
853	        bar.sync();   // B2.6b: d visible to every CTA before the apply
854	        st.d_factor = d_bc[0];                      // the reduced d the tail reads
855	    }
