857	    // ── P2.7 (Muon ONLY): grid-cooperative Newton-Schulz orthogonalization of the
858	    //    2D weights (INTEGRATION-OPTSTAGES §3). PORT of the decoder/vit twins' P2.7
859	    //    (fused_decoder_megakernel.cuh / fused_vit_megakernel.cuh) onto the mamba
860	    //    constant tables — same shared opt_stages_precompute.cuh helpers, same barrier
861	    //    sequence; only the per-model 2D table (mbtc::kMbMuon2D, 13 matrices incl.
862	    //    tok[99,128]/pos[8,128]/A_log[256,16]/dt_proj[256,8]/x_proj[40,256]) and offset
863	    //    array (kMambaOffsets) differ. For EACH 2D matrix all CTAs cooperate: buf=μ·buf+g
864	    //    (buf is the PERSISTENT m-slice — momentum state, NOT transient), ‖buf‖_F via
865	    //    per-CTA partials → inv_norm, X=buf·inv_norm, then ns_steps × { A=XXᵀ → AX=A·X →
866	    //    AAX=A·AX → orth=a·X+b·AX+c·AAX, swap }, then the canonical muon_update_step apply
867	    //    (decay·p + neg_lr_scale·orth). The 1D / non-2D weights (D, conv1d.weight/bias,
868	    //    dt_proj.bias, LN γ/β, out.bias) take the AdamW aux tail in P3. The elementwise
869	    //    bodies CALL muon.h (muon_momentum_normalize_step via the phaseA buf body,
870	    //    muon_ns_combine_step, muon_update_step); the matmuls are the cited new device
871	    //    code (the eager path delegates to torch::mm/cuBLAS). Guarded so every other opt is
872	    //    byte-identical (no extra barriers / work).
873	    //    DETERMINISM (the A/A/A leg the gate verifies): muon/mamba is a SINGLE forward +
874	    //    NS precompute — it does NOT re-run the mamba forward (unlike the SAM-2nd-pass
875	    //    mamba cells looksam/SG11/15 which hit the shared mamba-forward A/A/A race), and the
876	    //    P2.7 reductions are fixed-ownership ascending-CTA (muon_norm_reduce_phaseB sums
877	    //    nrm_partials[0..nCTA) in ascending index) + the NS matmuls are deterministic
878	    //    grid-cooperative tiles — so the phase is deterministic BY CONSTRUCTION. The gate
879	    //    confirms A/A/A bit-identity; if it ever fails, the cell is landed-dormant (see
880	    //    the dispatch.cpp mb_muon carve-out scaffold).
881	    if constexpr (Opt == OptId::Muon) {
882	        // Carve the per-matrix NS scratch (sized for the largest 2D weight).
883	        PrecomputeWorkspace pw{};
884	        pw.muon_X            = muon_base;
885	        pw.muon_AX           = pw.muon_X   + mbtc::kMbMuonMaxNumel;
886	        pw.muon_AAX          = pw.muon_AX  + mbtc::kMbMuonMaxNumel;
887	        pw.muon_orth         = pw.muon_AAX + mbtc::kMbMuonMaxNumel;
888	        pw.muon_A            = pw.muon_orth + mbtc::kMbMuonMaxNumel;
889	        pw.muon_nrm_partials = pw.muon_A   + (int64_t)mbtc::kMbMuonMaxRows * mbtc::kMbMuonMaxRows;
890	        pw.muon_inv_norm     = pw.muon_nrm_partials + nCTA;
891	        const float momentum = st.beta1;          // Muon momentum (eager Muon: betas[0])
892	        const int   ns_steps = 5;                 // bindings.cpp default
893	        for (int mi = 0; mi < mbtc::kMbNumMuon2D; ++mi) {
894	            const mbtc::MbMuon2D M = mbtc::kMbMuon2D[mi];
895	            const int rows = M.rows, cols = M.cols;
896	            const int64_t numel = (int64_t)rows * cols;
897	            const int64_t off   = (int64_t)kMambaOffsets[M.tidx];
898	            // buf = the PERSISTENT momentum slice for this matrix (st.exp_avg+off).
899	            pw.muon_buf = st.exp_avg + off;
900	            // phaseA: buf=μ·buf+g, publish per-CTA ‖buf‖_F² → reduce → inv_norm → X.
901	            muon_momentum_norm_phaseA(grad + off, numel, momentum, pw);
902	            bar.sync();
903	            muon_norm_reduce_phaseB(ctx, pw);
904	            bar.sync();
905	            muon_scale_X(numel, pw);
906	            bar.sync();
907	            // NS iterations. After each combine, orth holds the new iterate; swap so
908	            // the next iteration reads it as X. ns_steps swaps → final result is in
909	            // muon_X (the last combine wrote muon_orth, then we swapped → muon_X).
910	            for (int s = 0; s < ns_steps; ++s) {
911	                // A = X Xᵀ  (M=rows,N=rows,K=cols; B transposed).
912	                muon_matmul(pw.muon_X, pw.muon_X, pw.muon_A, rows, rows, cols, cols, cols, /*bT=*/true);
913	                bar.sync();
914	                // AX = A X   (M=rows,N=cols,K=rows).
915	                muon_matmul(pw.muon_A, pw.muon_X, pw.muon_AX, rows, cols, rows, rows, cols, /*bT=*/false);
916	                bar.sync();
917	                // AAX = A (AX) (M=rows,N=cols,K=rows).
918	                muon_matmul(pw.muon_A, pw.muon_AX, pw.muon_AAX, rows, cols, rows, rows, cols, /*bT=*/false);
919	                bar.sync();
920	                muon_ns_combine_phase(numel, pw);   // orth = a·X + b·AX + c·AAX
921	                bar.sync();
922	                float* tmp = pw.muon_X; pw.muon_X = pw.muon_orth; pw.muon_orth = tmp;
923	            }
924	            // Apply Muon: p = decay_factor·p + neg_lr_scale·orth  (muon.h:63-73).
925	            const float scale        = 0.2f * sqrtf((float)(rows > cols ? rows : cols));
926	            const float neg_lr_scale = -lr * scale;
927	            const float decay_factor = 1.0f - lr * st.wd;
928	            float* __restrict__ p = params + off;
929	            const float* __restrict__ orth_final = pw.muon_X;   // post-swap result
930	            const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
931	            for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; i < numel; i += gstride)
932	                p[i] = decay_factor * p[i] + neg_lr_scale * orth_final[i];
933	            bar.sync();   // matrix done; all CTAs synchronized before the next matrix
934	        }
935	    }
