937	    // ── P3: the REAL optimizer tail over the reduced grad (work-steal 28). ──
938	    st.lr = lr;
939	    {
940	        __shared__ int task_slot;
941	        TaskQueue q = ctx.queue();
942	        for (int t = q.next_block(&task_slot); t < kMambaNumTensors;
943	             t = q.next_block(&task_slot)) {
944	            const int n = kMambaSizes[t];
945	            const int64_t off = (int64_t)kMambaOffsets[t];
946	            // MUON: the 2D matrices were orthogonalized + applied in P2.7; P3 handles
947	            //   ONLY the 1D / non-2D weights, which take the AdamW tail (muon.h:75-76,
948	            //   the eager Muon auto-split). Skip the 2D ones here (already done).
949	            if constexpr (Opt == OptId::Muon) {
950	                if (mbtc::mb_is_muon_2d(t)) continue;
951	            }
952	            FusedOptState ts = mamba_rebase_state<Opt>(st, off);
953	            // (i) PER-TENSOR LAYER-WISE β1 (GrokAdamW only) — PORT of the decoder
954	            //     P3 (fused_decoder_megakernel.cuh:587-591): β1_i = β1·(1-γ)^t, where
955	            //     t == the tensor's flat named_parameters() layer index (the work-steal
956	            //     task id maps 1:1 to kMambaOffsets order == the eager enumeration
957	            //     order, so t IS the eager layer index). bc1 must be rebased TOO
958	            //     (= 1-β1_i^step) or m_hat=m/bc1 mismatches eager; bc2 stays global
959	            //     (β2 is not layer-wise). This is the mechanism that fails the STEP-1
960	            //     STATE gate when dropped (decoder observed m-rel 0.895).
961	            if constexpr (Opt == OptId::GrokAdamW) {
962	                const float b1 = st.beta1 * powf(1.0f - st.gamma, (float)t);
963	                ts.beta1 = b1;
964	                ts.bc1   = 1.0f - powf(b1, (float)step);
965	            }
966	            float* __restrict__ p = params + off;
967	            const float* __restrict__ gg = grad + off;
968	            if constexpr (Opt == OptId::Muon) {
969	                // 1D / non-2D weights: the canonical AdamW tail (muon.py:99-125 routes
970	                // non-matrix params to a SEPARATE AdamW group with INDEPENDENT
971	                // hyperparameters — adamw_lr/adamw_betas — NOT the 2D Muon lr/momentum).
972	                // ts.lr/ts.beta1 carry the 2D-group's (lr=0.02, momentum=0.95), so the
973	                // 1D tail MUST instead use the aux_* fields (eager adamw_lr/adamw_betas).
974	                // weight_decay is SHARED across both eager groups (muon.py:122) → ts.wd
975	                // stays. eps is the eager adamw_eps (= ts.eps, mapped by _opt_scalars_from).
976	                // bc1/bc2 are device-computed from aux_beta^step (kept out of the mirror
977	                // to shrink the host ABI; fp32 powf, tol 2e-3 ample). apply_optimizer<Muon>
978	                // would deref st.orth (NS dir, only valid for 2D), so route directly to
979	                // adamw_step with the aux hyperparameters — IDENTICAL to the decoder/vit twins.
980	                const float a_bc1 = 1.0f - powf(st.aux_beta1, (float)step);
981	                const float a_bc2 = 1.0f - powf(st.aux_beta2, (float)step);
982	                for (int i = threadIdx.x; i < n; i += blockDim.x)
983	                    algo::adamw_step<float, float>(
984	                        p, ts.exp_avg, ts.exp_avg_sq, gg,
985	                        st.aux_lr, st.aux_beta1, st.aux_beta2, ts.eps, ts.wd,
986	                        a_bc1, a_bc2, (int64_t)i);
987	            } else {
988	                for (int i = threadIdx.x; i < n; i += blockDim.x)
989	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
990	            }
991	        }
992	    }
993	    SG_MBTC_PROF_ACC(3, _pt);          // close P3
