996	// Launcher (static-smem; the decoder TC contract). ncta_cap>0 caps the launched
997	// CTAs (the per-CTA scratch is nCTA×slab; a memory-tight TEST caps it). Grid
998	// barrier rendezvous is over the LAUNCHED count → hang-safe; determinism is per
999	// fixed nCTA (dW-tile / partial / embed owner maps read ctx.n_ctas). B%16 req.
1000	// Host helper: the EXACT CTA count launch_fused_mamba_megakernel_tc<Opt> will use
1001	// (occ·n_sms with occupancy-fill, or the cap). The caller MUST size the workspace
1002	// with this — the per-CTA scratch/partials are nCTA·slab, so sizing for n_sms while
1003	// the launcher runs occ·n_sms would overflow. Returns 0 on a CUDA-attr failure (the
1004	// caller should treat that as "fall back to a conservative larger size").
1005	template <OptId Opt>
1006	int mb_tc_launched_nctas(int dev, int ncta_cap) {
1007	    int n_sms = 0;
1008	    if (cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev) != cudaSuccess) return 0;
1009	    int occ = 0;
1010	    if (cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1011	            &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK, 0) != cudaSuccess)
1012	        return 0;
1013	    if (occ < 1) return 0;
1014	    unsigned waves = (SG_MBTC_MIN_BLOCKS_PER_SM >= 2 && occ > 1) ? (unsigned)occ : 1u;
1015	    unsigned launch_ctas = (unsigned)n_sms * waves;
1016	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1017	    return (int)launch_ctas;
1018	}
